import React, { useEffect, useState } from 'react';
import { useParams, useNavigate, Link } from 'react-router-dom';
import toast from 'react-hot-toast';
import { projectsAPI, contractsAPI } from '../../services/api';
import AppLayout from '../../components/layout/AppLayout';

export default function ProjectDetailPage() {
  const { id } = useParams();
  const navigate = useNavigate();
  const [project, setProject] = useState(null);
  const [contracts, setContracts] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    Promise.all([projectsAPI.get(id), contractsAPI.list(id)])
      .then(([p, c]) => { setProject(p.data); setContracts(c.data); })
      .catch(() => { toast.error('Projet introuvable'); navigate('/projects'); })
      .finally(() => setLoading(false));
  }, [id, navigate]);

  const handleDelete = async () => {
    if (!window.confirm('Supprimer ce projet ?')) return;
    await projectsAPI.delete(id);
    toast.success('Projet supprimé');
    navigate('/projects');
  };

  if (loading) return <AppLayout><div style={{ display:'flex', justifyContent:'center', padding:80 }}><div style={{ width:40, height:40, border:'3px solid #F59E0B', borderTopColor:'transparent', borderRadius:'50%', animation:'spin 1s linear infinite' }} /></div></AppLayout>;
  if (!project) return null;

  const statusColors = { en_cours:'#10B981', termine:'#3B82F6', suspendu:'#EF4444', planifie:'#F59E0B' };
  const statusLabels = { en_cours:'En cours', termine:'Terminé', suspendu:'Suspendu', planifie:'Planifié' };

  return (
    <AppLayout>
      <div style={{ padding:'32px 40px' }} className="animate-fade-in">
        <div style={{ display:'flex', justifyContent:'space-between', alignItems:'flex-start', marginBottom:32, flexWrap:'wrap', gap:16 }}>
          <div>
            <button onClick={() => navigate('/projects')} style={{ background:'none', border:'none', color:'#6B7280', cursor:'pointer', fontSize:14, marginBottom:8, fontFamily:'Barlow', display:'flex', alignItems:'center', gap:6 }}>
              ← Retour aux projets
            </button>
            <h1 style={{ fontFamily:'Bebas Neue', fontSize:38, color:'#fff', letterSpacing:1, margin:'0 0 8px' }}>{project.name}</h1>
            <div style={{ display:'flex', gap:12, alignItems:'center', flexWrap:'wrap' }}>
              <span style={{ padding:'4px 12px', borderRadius:100, fontSize:13, fontWeight:600, background:`${statusColors[project.status]}20`, color:statusColors[project.status] }}>
                {statusLabels[project.status]}
              </span>
              {project.location && <span style={{ fontSize:14, color:'#6B7280' }}>📍 {project.location}</span>}
            </div>
          </div>
          <div style={{ display:'flex', gap:10 }}>
            <Link to={`/contracts/upload?project=${id}`} className="btn btn-primary btn-sm">+ Analyser contrat</Link>
            <button onClick={handleDelete} className="btn btn-ghost btn-sm" style={{ color:'#EF4444', borderColor:'rgba(239,68,68,0.3)' }}>Supprimer</button>
          </div>
        </div>

        <div style={{ display:'grid', gridTemplateColumns:'2fr 1fr', gap:24 }}>
          {/* Left */}
          <div style={{ display:'flex', flexDirection:'column', gap:24 }}>
            {project.description && (
              <div className="card">
                <h3 style={{ fontFamily:'Barlow Condensed', fontSize:16, color:'#9CA3AF', letterSpacing:0.5, textTransform:'uppercase', margin:'0 0 12px', fontWeight:600 }}>Description</h3>
                <p style={{ color:'#D1D5DB', lineHeight:1.7 }}>{project.description}</p>
              </div>
            )}

            {/* Contracts */}
            <div className="card">
              <div style={{ display:'flex', justifyContent:'space-between', alignItems:'center', marginBottom:20 }}>
                <h3 style={{ fontFamily:'Barlow Condensed', fontSize:16, color:'#9CA3AF', letterSpacing:0.5, textTransform:'uppercase', margin:0, fontWeight:600 }}>
                  Contrats analysés ({contracts.length})
                </h3>
                <Link to={`/contracts/upload?project=${id}`} style={{ fontSize:13, color:'#F59E0B', textDecoration:'none', fontFamily:'Barlow Condensed', fontWeight:600 }}>+ Ajouter</Link>
              </div>
              {contracts.length === 0 ? (
                <div style={{ textAlign:'center', padding:32 }}>
                  <div style={{ fontSize:36, marginBottom:12 }}>📄</div>
                  <p style={{ color:'#6B7280', marginBottom:16 }}>Aucun contrat analysé</p>
                  <Link to={`/contracts/upload?project=${id}`} className="btn btn-outline btn-sm">Analyser un contrat</Link>
                </div>
              ) : (
                <div style={{ display:'flex', flexDirection:'column', gap:12 }}>
                  {contracts.map(c => (
                    <Link key={c.id} to={`/contracts/${c.id}`} style={{ textDecoration:'none' }}>
                      <div style={{ display:'flex', alignItems:'center', gap:12, padding:'12px 16px', background:'rgba(255,255,255,0.03)', borderRadius:8, border:'1px solid rgba(255,255,255,0.06)', cursor:'pointer', transition:'all 0.2s' }}
                        onMouseEnter={e => e.currentTarget.style.background = 'rgba(245,158,11,0.05)'}
                        onMouseLeave={e => e.currentTarget.style.background = 'rgba(255,255,255,0.03)'}>
                        <span style={{ fontSize:20 }}>📄</span>
                        <div style={{ flex:1, minWidth:0 }}>
                          <p style={{ margin:0, fontSize:14, fontWeight:600, color:'#fff', whiteSpace:'nowrap', overflow:'hidden', textOverflow:'ellipsis' }}>{c.file_name}</p>
                          <p style={{ margin:0, fontSize:12, color:'#6B7280' }}>{new Date(c.created_at).toLocaleDateString('fr-FR')}</p>
                        </div>
                        <span style={{ padding:'3px 8px', borderRadius:100, fontSize:11, fontWeight:600,
                          background: c.status === 'completed' ? 'rgba(16,185,129,0.15)' : c.status === 'error' ? 'rgba(239,68,68,0.15)' : 'rgba(245,158,11,0.15)',
                          color: c.status === 'completed' ? '#10B981' : c.status === 'error' ? '#EF4444' : '#F59E0B' }}>
                          {c.status === 'completed' ? '✓ Analysé' : c.status === 'error' ? '✗ Erreur' : '⏳ Traitement'}
                        </span>
                      </div>
                    </Link>
                  ))}
                </div>
              )}
            </div>
          </div>

          {/* Right - Info */}
          <div style={{ display:'flex', flexDirection:'column', gap:16 }}>
            <div className="card">
              <h3 style={{ fontFamily:'Barlow Condensed', fontSize:16, color:'#9CA3AF', letterSpacing:0.5, textTransform:'uppercase', margin:'0 0 16px', fontWeight:600 }}>Informations</h3>
              <div style={{ display:'flex', flexDirection:'column', gap:12 }}>
                {[
                  { label:'Type', value: project.project_type },
                  { label:'Début', value: project.start_date ? new Date(project.start_date).toLocaleDateString('fr-FR') : 'Non défini' },
                  { label:'Fin', value: project.end_date ? new Date(project.end_date).toLocaleDateString('fr-FR') : 'Non défini' },
                  { label:'Budget', value: project.budget ? `${Number(project.budget).toLocaleString('fr-FR')} FCFA` : 'Non défini' },
                  { label:'Créé le', value: new Date(project.created_at).toLocaleDateString('fr-FR') },
                ].map(item => (
                  <div key={item.label} style={{ display:'flex', justifyContent:'space-between', padding:'8px 0', borderBottom:'1px solid rgba(255,255,255,0.06)' }}>
                    <span style={{ fontSize:13, color:'#6B7280' }}>{item.label}</span>
                    <span style={{ fontSize:13, color:'#D1D5DB', fontWeight:500 }}>{item.value}</span>
                  </div>
                ))}
              </div>
            </div>
          </div>
        </div>
      </div>
    </AppLayout>
  );
}
